def analyze_block(component): body = block_body(component) locals = scan_out_declarations(body) unassigneds = list_of_unassigned(locals) bfun = analyze(body) return lambda env, succeed, fail: (bfun(extend_environment(locals, unassigneds, env), succeed, fail))

